function mostBoxPoints(boxes: number[]): number {
  const memo = new Map<string, number>();
  const go = (b: number[]): number => {
    if (b.length === 0) return 0;
    const key = b.join(",");
    const hit = memo.get(key);
    if (hit !== undefined) return hit;
    let best = 0;
    for (let i = 0; i < b.length; ) {
      let j = i;
      while (j < b.length && b[j] === b[i]) j++;
      best = Math.max(best, (j - i) * (j - i) + go(b.slice(0, i).concat(b.slice(j))));
      i = j;
    }
    memo.set(key, best);
    return best;
  };
  return go(boxes);
}

