function mostBoxPoints(boxes: number[]): number {
  const n = boxes.length;
  const memo = new Int32Array(n * n * n).fill(-1);
  const go = (l: number, r: number, k: number): number => {
    if (l > r) return 0;
    while (l < r && boxes[l + 1] === boxes[l]) { l++; k++; }
    const key = (l * n + r) * n + k;
    if (memo[key] >= 0) return memo[key];
    let best = (k + 1) * (k + 1) + go(l + 1, r, 0);
    for (let m = l + 2; m <= r; m++) {
      if (boxes[m] === boxes[l] && boxes[m - 1] !== boxes[l]) {
        best = Math.max(best, go(l + 1, m - 1, 0) + go(m, r, k + 1));
      }
    }
    memo[key] = best;
    return best;
  };
  return go(0, n - 1, 0);
}

