class Solution:
    def mostBoxPoints(self, boxes: List[int]) -> int:
        memo = {}

        def go(l, r, k):
            if l > r:
                return 0
            while l < r and boxes[l + 1] == boxes[l]:
                l += 1
                k += 1
            key = (l, r, k)
            if key in memo:
                return memo[key]
            best = (k + 1) ** 2 + go(l + 1, r, 0)
            for m in range(l + 2, r + 1):
                # only the first box of each same-colored run is worth joining
                if boxes[m] == boxes[l] and boxes[m - 1] != boxes[l]:
                    best = max(best, go(l + 1, m - 1, 0) + go(m, r, k + 1))
            memo[key] = best
            return best

        return go(0, len(boxes) - 1, 0)

